import React, { useEffect, useState } from 'react';

const UserStatistics = () => {
  const [users, setUsers] = useState(0);
  const [gold, setGold] = useState(0);

  useEffect(() => {
    const animateNumbers = () => {
      let userCount = 0;
      let goldCount = 0;

      const userInterval = setInterval(() => {
        if (userCount < 265603975) {
          userCount += 100000;
          setUsers(userCount);
        } else {
          clearInterval(userInterval);
        }
      }, 10);

      const goldInterval = setInterval(() => {
        if (goldCount < 265603864) {
          goldCount += 100000;
          setGold(goldCount);
        } else {
          clearInterval(goldInterval);
        }
      }, 10);
    };

    animateNumbers();
  }, []);

  return (
    <div className="statsContainer">
      <div className="statCard">
        <div className="statHeader">USERS</div>
        <div className="statValue">{users.toLocaleString()}</div>
      </div>
      <div className="statCard">
        <div className="statHeader">IN GOLD</div>
        <div className="statValue">{gold.toLocaleString()}</div>
      </div>
    </div>
  );
};

export default UserStatistics;
